168: class _AppLocalizationsDelegate
169:     extends LocalizationsDelegate<AppLocalizations> {
170:   const _AppLocalizationsDelegate();
171: 
172:   @override
173:   Future<AppLocalizations> load(Locale locale) {
174:     return SynchronousFuture<AppLocalizations>(lookupAppLocalizations(locale));
175:   }
176: 
177:   @override
178:   bool isSupported(Locale locale) =>
179:       <String>['en', 'ru'].contains(locale.languageCode);
180: 
181:   @override
182:   bool shouldReload(_AppLocalizationsDelegate old) => false;
183: }
184: 
185: AppLocalizations lookupAppLocalizations(Locale locale) {
186:   // Lookup logic when only language code is specified.
187:   switch (locale.languageCode) {
188:     case 'en':
189:       return AppLocalizationsEn();
190:     case 'ru':
191:       return AppLocalizationsRu();
192:   }
193: 
194:   throw FlutterError(
195:       'AppLocalizations.delegate failed to load unsupported locale "$locale". This is likely '
196:       'an issue with the localizations generation tool. Please file an issue '
197:       'on GitHub with a reproducible sample app and the gen-l10n configuration '
198:       'that was used.');
199: }

