{"content":"import 'package:flutter/material.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage>
    with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late Future<List<CurrencyModel>> _currencyListFuture;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  int _pageSize = 20;
  bool _hasMore = true;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      _refreshWithUsdBase();
    }
  }

  Future<void> _refreshWithUsdBase() async {
    setState(() {
      _currentPage = 0;
      _allCurrencies = [];
      _hasMore = true;
      _filteredCurrenciesNotifier.value = [];
    });
    await _loadPage(const CurrencyPageRequest(base: 'USD', page: 0));
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadPage(CurrencyPageRequest request) async {
    final currencyRepository = context.read<CurrencyRepository>();
    try {
      final CurrencyPage page = await currencyRepository.fetchRates(request);
      if (!mounted) return;

      setState(() {
        if (request.page == 0) {
          _allCurrencies = List.from(page.items);
        } else {
          _allCurrencies = [..._allCurrencies, ...page.items];
        }
        _currentPage = page.page + 1;
        _hasMore = page.hasMore;
        _filteredCurrenciesNotifier.value = List.from(_allCurrencies);

        if (request.page == 0) {
          _fadeController.forward();
        }
      });

      currencyRepository.saveCurrencyList(page.items);
    } catch (_) {
      if (!mounted) return;
      setState(() {
        _hasMore = false;
      });
    }
  }

  void _initData() {
    _filteredCurrenciesNotifier = ValueNotifier([]);
    _loadPage(const CurrencyPageRequest(base: 'USD', page: 0));
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((
      CurrencyModel currency,
    ) {
      return currency.name.toLowerCase().contains(lowerQuery) ||
          currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = List.from(result);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder<List<CurrencyModel>>(
        future: _currencyListFuture,
        builder: (BuildContext context, AsyncSnapshot snapshot) {
          final List<CurrencyModel>? data = snapshot.data;
          if (data == null || data.isEmpty && _allCurrencies.isEmpty) {
            return const SizedBox.shrink();
          }

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding:
                      const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data,
                        _) {
                      return ListView.builder(
                        itemCount: data.length + (_hasMore ? 1 : 0),
                        itemBuilder: (BuildContext context, int index) {
                          if (index == data.length && _hasMore) {
                            return Center(
                              child: Padding(
                                padding: const EdgeInsets.all(16.0),
                                child: TextButton(
                                  onPressed: () {
                                    _loadPage(CurrencyPageRequest(
                                      base: 'USD',
                                      page: _currentPage,
                                      pageSize: _pageSize,
                                    ));
                                  },
                                  child: Text(context.loc.showMore),
                                ),
                              ),
                            );
                          }

                          final CurrencyModel currency = data[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0
                                ? const EdgeInsets.only(top: 20)
                                : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding:
                            const EdgeInsets.fromLTRB(22, 0, 22, 40),
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
